package com.codegym.controller;
import com.codegym.model.Customer; import com.codegym.service.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet(name="CustomerServlet",urlPatterns="/customers") public class CustomerServlet extends HttpServlet { private final CustomerService service=new CustomerServiceImpl(); private void forward(HttpServletRequest r,HttpServletResponse s,String path)throws ServletException,IOException{s.getRequestDispatcher(path).forward(r,s);} private int id(HttpServletRequest r){return Integer.parseInt(r.getParameter("id"));} protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String a=r.getParameter("action"); if(a==null||a.isBlank()){r.setAttribute("customers",service.findAll());forward(r,s,"/customer/list.jsp");return;} Customer c; switch(a){case "create":forward(r,s,"/customer/create.jsp");break;case "edit":case "delete":case "view":c=service.findById(id(r));if(c==null){forward(r,s,"/error-404.jsp");}else{r.setAttribute("customer",c);forward(r,s,"/customer/"+(a.equals("view")?"view":a)+".jsp");}break;default:s.sendError(404);}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String a=r.getParameter("action");try{if("create".equals(a)){int n=service.findAll().stream().mapToInt(Customer::getId).max().orElse(0)+1;service.save(new Customer(n,r.getParameter("name"),r.getParameter("email"),r.getParameter("address")));}else if("edit".equals(a)){int n=id(r);if(service.findById(n)==null){forward(r,s,"/error-404.jsp");return;}service.update(n,new Customer(n,r.getParameter("name"),r.getParameter("email"),r.getParameter("address")));}else if("delete".equals(a)){if(service.findById(id(r))==null){forward(r,s,"/error-404.jsp");return;}service.remove(id(r));}s.sendRedirect(r.getContextPath()+"/customers");}catch(NumberFormatException e){forward(r,s,"/error-404.jsp");}}}
